head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > getModifiedArray]<br/>Row 의 상태가 '갱신', '삽입', '삭제', '제거' 인 Row 데이터와 Column 의 ID 정보를 객체로 반환합니다.",
    "validation" : [
        "필터와 정렬이 적용된 상태를 기준으로 Row 상태값이 'U', 'C', 'D', 'E' 인 Row 데이터가 반환됩니다.",
        "options(선택) 파라미터로 반환받을 Row 데이터의 추가 조건을 JSON 형태의 객체로 설정합니다.",
        "options(선택) 파라미터를 설정하지 않으면 saveRemovedData 속성이 true 로 적용됩니다.",
        "options.saveRemovedData(선택) 파라미터로 Row 상태값이 'E' 인 '제거' Row 의 데이터를 포함할지 true/false 로 설정합니다.",
        "options.saveRemovedData(선택) 파라미터로 미설정 또는 true 설정 시 Row 상태값이 'E' 인 Row 데이터를 반환값에 포함합니다.",
        "options.saveRemovedData(선택) 파라미터로 false 설정 시 Row 상태값이 'E' 인 Row 데이터를 반환값에 포함하지 않습니다.",
        "반환값으로 DataList 모듈에 정의된 Column 의 ID 정보와 Row 의 상태가 '갱신', '삽입', '삭제', '제거' 인 Row 데이터를 각각 배열로 갖는 객체를 반환합니다.",
        "반환된 객체의 columnInfo 속성값으로 DataList 모듈에 정의된 Column 의 ID 정보를 1차원 배열로 갖습니다.",
        "반환된 객체의 data 속성값으로 필터와 정렬이 적용된 상태를 기준으로 Row 의 상태가 '갱신', '삽입', '삭제', '제거' 인 데이터를 1차원 배열로 갖습니다.",
        "Row 의 상태값이 'U', 'C', 'D', 'E' 인 Row 가 반환되며, '삽입 후 삭제' 된 'V' 상태의 Row 데이터는 포함되지 않습니다.",
        "반환되는 배열은 정렬이 적용된 순서대로 생성되며, 'E' 상태인 Row 는 마지막에 생성됩니다.",
        "DataList 모듈에 필터가 적용되지 않은 경우 전체 Row 데이터를 기준으로 처리됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');

    scwin.btn_insertRow_onclick();
    scwin.btn_deleteRow_onclick();
    scwin.btn_setCellData_onclick();
    scwin.btn_removeRow_onclick();
    scwin.btn_insertDeleteRow_onclick();
}   



scwin.btn_insertRow_onclick = function (e) {
    let insertIndex = target1.insertRow();
    target1.setRowData(insertIndex,["insert1","insert2","insert3","insert4"],true);
};



scwin.btn_deleteRow_onclick = function (e) {
    target1.deleteRow(0);
};



scwin.btn_setCellData_onclick = function (e) {
    target1.setCellData(2, "col1", "change");
};



scwin.btn_removeRow_onclick = function (e) {
    target1.removeRow(3);
}



scwin.btn_insertDeleteRow_onclick = function (e) {
    let insertIndex = target1.insertRow();
    target1.setRowData(insertIndex,["insert5","insert6","insert7","insert8"],true);

    target1.deleteRow(insertIndex);
};



scwin.btn_setColumnFilter_onclick = function (e) {
	target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_2", condition:'and'})    
    target1.setColumnFilter( {type:'row', colIndex:'col1', key:"insert1", condition:'or'})
};



scwin.btn_sort_onclick = function (e) {
    target1.sort("col1", 1);
};



scwin.btn_getModifiedArray_onclick = function (e) {
    let rtn = '';
    let options = par_options.getText();

    if (options == "")
        rtn = target1.getModifiedArray();
    else
        rtn = target1.getModifiedArray(eval('(' + options + ')'));

    wf_body_bottom.getObj("scwin").setReturnValue("result: " + rtn);
    wf_body_bottom.getObj("scwin").setReturnValue("result.columnInfo: " + rtn.columnInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("result.data: " + rtn.data);
};
